    if (url.pathname === '/orders' && req.method === 'POST') {
      const body = await req.json();
      await env.DB.prepare('INSERT INTO orders (qty) VALUES (?)').bind(body.qty).run();
      return new Response('ok');
    }
    return new Response('not found', { status: 404 });
  },
